  writes.forEach((w, i) => {
    const d = byId[w.doseId] || null;
    const line = describe(d || { brandName: w.doseId }, w.status, language, d ? spokenTime : null);
    (codes[i] === 200 ? ok : bad).push({ line, dose: d });
